  INSERT INTO public.blog_post_sources (post_id, position, name, url, publisher)
  SELECT new_id, s.position, s.name, s.url, s.publisher
  FROM (VALUES
      (0, 'Forms of payment (debit cards)', 'https://www.enterprise.com/en/car-rental-faqs/us-deposits-and-payments/forms-of-payment.html', 'Enterprise'),
      (1, 'Renting with debit cards', 'https://www.alamo.com/en/customer-support/car-rental-faqs/renting-with-debit-cards.html', 'Alamo'),
      (2, 'Payment methods', 'https://www.nationalcar.com/en/support/car-rental-faqs/payment-methods.html', 'National'),
      (3, 'Credit and debit cards', 'https://www.hertz.com/us/en/about-us/credit-debit-cards', 'Hertz'),
      (4, 'Fort Lauderdale-Hollywood Intl. Airport location and rental terms', 'https://www.avis.com/en/locations/us/fl/fort-lauderdale/fll', 'Avis'),
      (5, 'Rent with a debit card', 'https://www.budget.com/en/help/usa-faqs/rent-with-debit-card', 'Budget'),
      (6, 'Debit card policy', 'https://www.dollar.com/travelcenter/traveltools/debitcardpolicy.aspx', 'Dollar'),
      (7, 'Debit card policy', 'https://www.thrifty.com/travelcenter/traveltools/debitcardpolicy.aspx', 'Thrifty'),
      (8, 'Renting a car under 25', 'https://www.enterprise.com/en/car-rental-faqs/us-renter-requirements/car-rental-under-25.html', 'Enterprise'),
      (9, 'Taxes, surcharges and fees', 'https://www.alamo.com/en/customer-support/car-rental-faqs/taxes-surcharges-fees.html', 'Alamo'),
