-- 02-places-to-go-fort-lauderdale-miami.md
DO $post$
DECLARE
  new_id uuid;
BEGIN
  INSERT INTO public.blog_posts
    (title, slug, excerpt, content, category_id, author, status,
     seo_title, meta_description, primary_keyword, cta_label, cta_url)
  VALUES (
    'Places to Go in Fort Lauderdale and Miami: A Local''s Guide',
    'places-to-go-fort-lauderdale-miami',
    'Beaches, zoos, museums and the local restaurants we send our own friends to. A road-trip-friendly guide to the best of Fort Lauderdale and Miami.',
    $json${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fort Lauderdale and Miami are only about 30 miles apart, but they feel like two different trips. Fort Lauderdale is laid-back: canals, beach bars and long walks on the sand. Miami is big and busy: art, music, Cuban coffee and neighborhoods that each feel like their own city."}]},{"type":"paragraph","content":[{"type":"text","text":"The best part? With a car, you can enjoy both in the same week. Here's where we'd send a friend visiting for the first time."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Beaches"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Fort Lauderdale and Broward County"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fort Lauderdale Beach.","marks":[{"type":"bold"}]},{"type":"text","text":" The classic. A wide beach along A1A with the wavy white wall and a promenade that's perfect for a sunset walk. Las Olas Boulevard ends right at the sand."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hugh Taylor Birch State Park.","marks":[{"type":"bold"}]},{"type":"text","text":" A quiet, shady park between the Intracoastal and the ocean, just north of the main beach. Walk under the trees, then cross A1A to the beach. There's a small per-vehicle entry fee."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Lauderdale-By-The-Sea.","marks":[{"type":"bold"}]},{"type":"text","text":" A small beach town with no high-rises on the sand, great snorkeling close to shore, and casual spots to eat on Commercial Boulevard."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hollywood Beach Broadwalk.","marks":[{"type":"bold"}]},{"type":"text","text":" About two and a half miles of brick promenade right on the beach, lined with cafés and ice cream shops. Great for bikes, strollers and people-watching."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Miami and Miami Beach"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"South Beach.","marks":[{"type":"bold"}]},{"type":"text","text":" Lummus Park runs along Ocean Drive with the famous colorful lifeguard stands and Art Deco buildings across the street. Go early for a quiet morning, stay for the scene later."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Crandon Park, Key Biscayne.","marks":[{"type":"bold"}]},{"type":"text","text":" Calm, shallow water and lots of room to spread out. A favorite with families. Parking is right behind the beach."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bill Baggs Cape Florida State Park.","marks":[{"type":"bold"}]},{"type":"text","text":" At the tip of Key Biscayne, with the Cape Florida Lighthouse. Tours up the lighthouse run several days a week."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Haulover Beach Park.","marks":[{"type":"bold"}]},{"type":"text","text":" A long, undeveloped stretch of sand between Bal Harbour and Sunny Isles. Locals come here to fly kites."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Zoos, animals and the Everglades"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Zoo Miami.","marks":[{"type":"bold"}]},{"type":"text","text":" Almost 750 acres and more than 2,000 animals, laid out by region so it feels more like a safari than a zoo. Wear good shoes; there are about four miles of paths. It's in southwest Miami-Dade, so a car makes it easy."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Flamingo Gardens, Davie.","marks":[{"type":"bold"}]},{"type":"text","text":" A 60-acre botanical garden and wildlife sanctuary west of Fort Lauderdale, home to rescued animals, including, yes, flamingos."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Butterfly World, Coconut Creek.","marks":[{"type":"bold"}]},{"type":"text","text":" Walk-through aviaries full of butterflies and birds. You can feed the lorikeets (bring a little cash)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everglades airboat ride.","marks":[{"type":"bold"}]},{"type":"text","text":" Everglades Holiday Park, west of Fort Lauderdale on Griffin Road, has been running airboat tours for more than 50 years, with alligator shows between rides."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Shark Valley, Everglades National Park.","marks":[{"type":"bold"}]},{"type":"text","text":" About 25 miles west of Miami on the Tamiami Trail. A two-hour tram tour takes you out to an observation tower over the sawgrass, usually past plenty of alligators. Book ahead in winter."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Museums and culture"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Miami"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pérez Art Museum Miami (PAMM).","marks":[{"type":"bold"}]},{"type":"text","text":" Modern and contemporary art in a beautiful building on Biscayne Bay. The shaded porch with hanging gardens is worth the trip on its own."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Frost Museum of Science.","marks":[{"type":"bold"}]},{"type":"text","text":" Right next to PAMM, with a three-level aquarium and a planetarium. Great for kids and rainy afternoons."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Vizcaya Museum & Gardens.","marks":[{"type":"bold"}]},{"type":"text","text":" A 1916 Italian-style estate and gardens on the bay in Coconut Grove. It's closed on Tuesdays, and some areas are under preservation work, so check before you go."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Wynwood Walls.","marks":[{"type":"bold"}]},{"type":"text","text":" Large murals by artists from around the world, surrounded by blocks of galleries, breweries and restaurants."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Little Havana.","marks":[{"type":"bold"}]},{"type":"text","text":" Walk Calle Ocho (SW 8th Street), watch the domino games at Máximo Gómez Park, and stop for a "},{"type":"text","text":"cafecito","marks":[{"type":"italic"}]},{"type":"text","text":" at a ventanita (walk-up window)."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Fort Lauderdale"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"NSU Art Museum.","marks":[{"type":"bold"}]},{"type":"text","text":" On Las Olas Boulevard downtown. Free for anyone 17 and under, and free for everyone on the first Thursday of the month."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bonnet House Museum & Gardens.","marks":[{"type":"bold"}]},{"type":"text","text":" An artists' estate hidden between the beach and the Intracoastal, with gardens, mangroves and a view of how Fort Lauderdale looked a century ago. Closed on Mondays."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Las Olas Boulevard and the Riverwalk.","marks":[{"type":"bold"}]},{"type":"text","text":" Shops, galleries and sidewalk cafés, plus a walk along the New River. The Water Taxi is a fun way to see the canals and the homes along them."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Local restaurants and hangouts"}]},{"type":"paragraph","content":[{"type":"text","text":"These are the places locals keep coming back to. Hours change seasonally, so check before you go."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Miami"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Versailles, Little Havana.","marks":[{"type":"bold"}]},{"type":"text","text":" The best-known Cuban restaurant in Miami, open since 1971. Get a "},{"type":"text","text":"cafecito","marks":[{"type":"italic"}]},{"type":"text","text":" and a "},{"type":"text","text":"pastelito","marks":[{"type":"italic"}]},{"type":"text","text":" at the walk-up window, or sit down for a Cuban sandwich."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ball & Chain, Little Havana.","marks":[{"type":"bold"}]},{"type":"text","text":" A Calle Ocho bar with live Latin music and dancing. It first opened in 1935."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"La Camaronera, Little Havana.","marks":[{"type":"bold"}]},{"type":"text","text":" A family seafood spot since 1976, famous for the "},{"type":"text","text":"pan con minuta","marks":[{"type":"italic"}]},{"type":"text","text":", a fried snapper sandwich."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Garcia's, Miami River.","marks":[{"type":"bold"}]},{"type":"text","text":" Fresh fish on the riverfront from a family that has been in the seafood business since the 1960s."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Joe's Stone Crab, South Beach.","marks":[{"type":"bold"}]},{"type":"text","text":" A Miami Beach institution. It opens for stone crab season in the fall and closes for part of the year, so check its site before you go."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Fort Lauderdale and Hollywood"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Mai-Kai, Oakland Park.","marks":[{"type":"bold"}]},{"type":"text","text":" A Polynesian restaurant and show that first opened in 1956, back after a major restoration. Order a tiki drink and stay for the show."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rustic Inn Crabhouse.","marks":[{"type":"bold"}]},{"type":"text","text":" Garlic crabs, cracked with a wooden mallet at a table covered in newspaper. Messy and worth it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"15th Street Fisheries.","marks":[{"type":"bold"}]},{"type":"text","text":" Waterfront seafood on the Lauderdale Marina. Feed the tarpon off the dock."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"LaSpada's Original Hoagies.","marks":[{"type":"bold"}]},{"type":"text","text":" A local favorite for big sub sandwiches. Grab one for the beach."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Le Tub Saloon, Hollywood.","marks":[{"type":"bold"}]},{"type":"text","text":" A quirky, open-air burger spot on the Intracoastal, decorated with old bathtubs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Jaxson's Ice Cream Parlour, Dania Beach.","marks":[{"type":"bold"}]},{"type":"text","text":" Open since 1956, with handmade ice cream and sundaes big enough to share."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Worth the drive south"}]},{"type":"paragraph","content":[{"type":"text","text":"If you have a free morning, drive to the farms south of Miami. "},{"type":"text","text":"Robert Is Here","marks":[{"type":"bold"}]},{"type":"text","text":" in Homestead is a family-owned fruit stand, open since 1959, known for its fresh fruit milkshakes. "},{"type":"text","text":"Knaus Berry Farm","marks":[{"type":"bold"}]},{"type":"text","text":", known for its cinnamon rolls, has moved to a new spot in southwest Miami-Dade. It's open in the cooler months, so check the season before you go."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"A few tips for getting around"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You'll want a car.","marks":[{"type":"bold"}]},{"type":"text","text":" The best beaches, the zoo, the Everglades and the farms are spread out, and rideshares add up fast."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Parking on Miami Beach is paid and limited.","marks":[{"type":"bold"}]},{"type":"text","text":" Use the city garages or the ParkMobile or PayByPhone apps."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tolls are cashless.","marks":[{"type":"bold"}]},{"type":"text","text":" Many highways here have no toll booths. With us, tolls are billed at cost at the end of your trip, with no extra toll fees."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Go early.","marks":[{"type":"bold"}]},{"type":"text","text":" Beaches, the zoo and the Everglades are best in the morning, before the heat and afternoon storms."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Let us handle the car"}]},{"type":"paragraph","content":[{"type":"text","text":"We're a local, family-owned rental company, and helping you enjoy South Florida is our favorite part of the job. We can meet you at "},{"type":"text","text":"FLL","marks":[{"type":"link","attrs":{"href":"/fort-lauderdale-airport-car-rental"}}]},{"type":"text","text":", bring the car to "},{"type":"text","text":"your hotel","marks":[{"type":"link","attrs":{"href":"/hotel-concierge-rentals"}}]},{"type":"text","text":", or have it ready before your "},{"type":"text","text":"cruise","marks":[{"type":"link","attrs":{"href":"/cruise-port-delivery"}}]},{"type":"text","text":". Get ideas with our "},{"type":"text","text":"trip planner","marks":[{"type":"link","attrs":{"href":"/trip-planner"}}]},{"type":"text","text":", then "},{"type":"text","text":"browse available cars","marks":[{"type":"link","attrs":{"href":"/book"}}]},{"type":"text","text":" for your dates."}]}]}$json$::jsonb,
