DO $post$
DECLARE
  new_id uuid;
BEGIN
  INSERT INTO public.blog_posts
    (title, slug, excerpt, content, category_id, author, status,
     seo_title, meta_description, primary_keyword, cta_label, cta_url)
  VALUES (
    'The Best Time of Year to Visit Fort Lauderdale and Miami',
    'best-time-to-visit-fort-lauderdale-miami',
    'Weather, rain, hurricane season and the big events, from Art Basel and the boat shows to Miami Music Week and Miami Spice. A month-by-month guide to planning your South Florida trip.',
    $json${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"There's no bad time to be in South Florida. But the best time for "},{"type":"text","text":"your","marks":[{"type":"italic"}]},{"type":"text","text":" trip depends on what you want: cool, dry beach days, a big event, or lower prices and quieter restaurants."}]},{"type":"paragraph","content":[{"type":"text","text":"Here's how the year works in Fort Lauderdale and Miami, from the weather to the events locals plan around."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The short answer"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Best weather:","marks":[{"type":"bold"}]},{"type":"text","text":" November through April. Warm days, cooler nights and much less rain."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Busiest and most expensive:","marks":[{"type":"bold"}]},{"type":"text","text":" mid-December through April, plus event weekends like Art Basel and Miami Music Week."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Best deals:","marks":[{"type":"bold"}]},{"type":"text","text":" late spring and summer, and again in September. It's hot and rainy, but hotels and restaurants are easier to book."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep an eye on the tropics:","marks":[{"type":"bold"}]},{"type":"text","text":" hurricane season runs June 1 through November 30, and it's most active from mid-August to mid-October."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Two seasons: dry and wet"}]},{"type":"paragraph","content":[{"type":"text","text":"South Florida really has two seasons."}]},{"type":"paragraph","content":[{"type":"text","text":"The dry season (roughly November to April)","marks":[{"type":"bold"}]},{"type":"text","text":" is what most visitors picture. Afternoon highs are in the upper 70s to low 80s°F, humidity drops, and rain is light. In Fort Lauderdale, December through March average under 3 inches of rain a month."}]},{"type":"paragraph","content":[{"type":"text","text":"The wet season (roughly late May to mid-October)","marks":[{"type":"bold"}]},{"type":"text","text":" is hot and humid, with highs around 90°F. The National Weather Service says the rainy season typically starts in late May and ends in mid-October, and that's when most of the year's rain falls. Mornings are often sunny, with a thunderstorm in the afternoon that passes in an hour or so. Plan beach time early and museums or lunch for the afternoon."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Month by month"}]},{"type":"paragraph","content":[{"type":"text","text":"Average highs, lows and rainfall below are for Fort Lauderdale-Hollywood International Airport (NOAA 1991–2020 normals). Miami runs within a degree or two."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Month"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"High / Low (°F)"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Rain (in)"}]}]},{"type":"tableHeader","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Worth knowing"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"January"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"76 / 61"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"2.9"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Peak season. Cool mornings, perfect beach afternoons"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"February"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"77 / 63"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"2.4"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Boat show, arts festival, wine and food festival"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"March"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"80 / 66"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"2.4"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Spring break, Calle Ocho, Miami Music Week, Ultra"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"April"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"83 / 70"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"3.0"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Warm and still dry. Tortuga, Formula 1 at month's end"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"May"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"86 / 74"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"5.6"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Heat builds; rainy season usually starts late in the month"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"June"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"88 / 77"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"9.6"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Hurricane season begins. Afternoon storms, lower prices"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"July"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"90 / 78"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"5.4"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Hot. Early beach days, indoor afternoons"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"August"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"90 / 78"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"7.9"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Miami Spice restaurant deals begin"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"September"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"88 / 77"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"8.0"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Quietest month. Peak of hurricane season"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"October"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"85 / 74"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"7.4"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Rain tapers off. Fort Lauderdale boat show season starts"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"November"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"81 / 68"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"3.7"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Dry season returns. Fort Lauderdale boat show, cruise season"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"December"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"78 / 65"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"2.8"}]}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Art Basel, the Winterfest Boat Parade, holiday crowds"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Events worth planning around"}]},{"type":"paragraph","content":[{"type":"text","text":"Dates below are the latest announced by each event. Plans can change, so check the official site before you book."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Fall: October to November"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fort Lauderdale International Boat Show","marks":[{"type":"bold"}]},{"type":"text","text":" (October 28 – November 1, 2026). One of the biggest boat shows in the world, spread across several waterfront locations around Fort Lauderdale. Hotels near the water fill up fast."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cruise season.","marks":[{"type":"bold"}]},{"type":"text","text":" Port Everglades' cruise season gets going in October. If you're sailing from Fort Lauderdale or Miami, it's worth having a car for a day or two before or after your cruise."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Winter: December to February"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Art Basel Miami Beach","marks":[{"type":"bold"}]},{"type":"text","text":" (public days December 4–6, 2026). The art fair at the Miami Beach Convention Center anchors a full week of satellite fairs, gallery openings and parties across Miami Beach, Wynwood and the Design District, often called Miami Art Week. It's one of the busiest weeks of the year for hotels and traffic."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Seminole Hard Rock Winterfest Boat Parade","marks":[{"type":"bold"}]},{"type":"text","text":" (Saturday, December 12, 2026). Lit-up boats cruise the New River and the Intracoastal Waterway in Fort Lauderdale. Organizers say more than a million people watch along the route."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Orange Bowl","marks":[{"type":"bold"}]},{"type":"text","text":" (College Football Playoff semifinal, January 14, 2027) at Hard Rock Stadium in Miami Gardens."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Miami International Boat Show","marks":[{"type":"bold"}]},{"type":"text","text":" (February 10–14, 2027), at the Miami Beach Convention Center and several waterfront venues."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Coconut Grove Arts Festival","marks":[{"type":"bold"}]},{"type":"text","text":" (February 13–15, 2027). Hundreds of artists set up at Regatta Park over Presidents' Day weekend."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"South Beach Wine & Food Festival","marks":[{"type":"bold"}]},{"type":"text","text":" (February 25–28, 2027). Chefs, tastings and beachside events on Miami Beach."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Spring: March to May"}]},{"type":"paragraph","content":[{"type":"text","text":"March is Miami's music month."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Calle Ocho Music Festival","marks":[{"type":"bold"}]},{"type":"text","text":" (March 14, 2027). A free street festival on SW 8th Street in Little Havana. Come hungry."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Miami Open","marks":[{"type":"bold"}]},{"type":"text","text":" tennis (March 14–28, 2027) at Hard Rock Stadium."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Winter Music Conference","marks":[{"type":"bold"}]},{"type":"text","text":", the long-running electronic music industry conference, returns to Downtown Miami in late March. Its site lists March 24–26, 2027."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Miami Music Week","marks":[{"type":"bold"}]},{"type":"text","text":" (March 22–28, 2027). More than 200 parties and shows across Miami and Miami Beach."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ultra Music Festival","marks":[{"type":"bold"}]},{"type":"text","text":" (March 26–28, 2027) at Bayfront Park in Downtown Miami, closing out Miami Music Week."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tortuga Music Festival","marks":[{"type":"bold"}]},{"type":"text","text":" on Fort Lauderdale Beach in early April. Check the festival site for dates and lineup."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Formula 1 Miami Grand Prix","marks":[{"type":"bold"}]},{"type":"text","text":" (April 30 – May 2, 2027) at the Miami International Autodrome, around Hard Rock Stadium."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fort Lauderdale Air Show","marks":[{"type":"bold"}]},{"type":"text","text":" (May 15–16, 2027), with the Blue Angels confirmed. The show has moved dates before, so check the site before you plan around it."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Summer: June to September"}]},{"type":"paragraph","content":[{"type":"text","text":"Summer is when locals get South Florida back. It's hot, it rains most afternoons, and it's the best time to find deals."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Miami Spice","marks":[{"type":"bold"}]},{"type":"text","text":" (August 1 – September 30 each year). Hundreds of Miami restaurants offer three-course prix-fixe menus. In 2026, brunch and lunch were $40 and dinner was $50 to $65. It's the easiest way to try places that are hard to book the rest of the year."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"A few tips from locals"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Book early for event weeks.","marks":[{"type":"bold"}]},{"type":"text","text":" Hotels, restaurants and rental cars get tight during Art Basel, the boat shows, Miami Music Week, Formula 1 and the winter holidays."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Plan around afternoon storms in summer.","marks":[{"type":"bold"}]},{"type":"text","text":" Beach in the morning, a museum or long lunch in the afternoon, sunset outside again."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Watch the tropics from August to October.","marks":[{"type":"bold"}]},{"type":"text","text":" If you're traveling then, check the "},{"type":"text","text":"National Hurricane Center","marks":[{"type":"link","attrs":{"href":"https://www.nhc.noaa.gov/"}}]},{"type":"text","text":" before you go and book plans you can change."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sun protection matters all year.","marks":[{"type":"bold"}]},{"type":"text","text":" Even in January, the sun is strong."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Parking is the hard part during big events.","marks":[{"type":"bold"}]},{"type":"text","text":" Having a car delivered to your hotel, and knowing where to park before you go, saves a lot of circling."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Whenever you come, we'll be here"}]},{"type":"paragraph","content":[{"type":"text","text":"We're a local, family-owned rental company in Fort Lauderdale and Miami. We can meet you at "},{"type":"text","text":"FLL","marks":[{"type":"link","attrs":{"href":"/fort-lauderdale-airport-car-rental"}}]},{"type":"text","text":", at "},{"type":"text","text":"your hotel","marks":[{"type":"link","attrs":{"href":"/hotel-concierge-rentals"}}]},{"type":"text","text":" or before your "},{"type":"text","text":"cruise","marks":[{"type":"link","attrs":{"href":"/cruise-port-delivery"}}]},{"type":"text","text":". Not sure where to start? Try our "},{"type":"text","text":"trip planner","marks":[{"type":"link","attrs":{"href":"/trip-planner"}}]},{"type":"text","text":", or "},{"type":"text","text":"browse available cars","marks":[{"type":"link","attrs":{"href":"/book"}}]},{"type":"text","text":" for your dates."}]}]}$json$::jsonb,
